// CreateTableWithDBType creates the Tax_Entry table for the specified company with the given database type
// The db parameter can be either *sql.DB or *sql.Tx
func (t *TaxEntry) CreateTableWithDBType(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, TaxEntryTableName)
	var schema string
	if dbType == database.DBTypePostgres {
		schema = GetTaxEntryPostgresTableSchema()
	} else {
		schema = GetTaxEntryTableSchema()
	}

	createSQL := fmt.Sprintf(`CREATE TABLE IF NOT EXISTS "%s" (%s)`, tableName, schema)
	_, err := db.Exec(createSQL)
	if err != nil {
		return fmt.Errorf("failed to create Tax_Entry table: %w", err)
	}

	// Indexes (Keys) and SIFT totals
	return t.SyncKeys(db, company, dbType)
}

// SyncKeys brings an existing table's keys up to date (table sync at startup): creates
// missing indexes and builds, rebuilds or drops the SIFT totals of keys with
// sum_index_fields (sift.Sync; unchanged keys cost one query).
func (t *TaxEntry) SyncKeys(db database.Executor, company string, dbType database.DBType) error {
	tableName := fmt.Sprintf("%s$%s", company, TaxEntryTableName)
	siftCompany := company
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (entry_no)`,
		fmt.Sprintf("%s$Tax_Entry$Primary", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index Primary: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (type, closed, tax_bus_posting_group, tax_prod_posting_group, tax_jurisdiction_code, use_tax, posting_date)`,
		fmt.Sprintf("%s$Tax_Entry$type_closed", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index type_closed: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (document_no, posting_date)`,
		fmt.Sprintf("%s$Tax_Entry$document", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index document: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (transaction_no)`,
		fmt.Sprintf("%s$Tax_Entry$transaction", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index transaction: %w", err)
	}
	// Index "company$Table$key"; a global table's indexes are shared by all companies:
	// "Table$key" (a company prefix created a copy of every index per company)
	if _, err := db.Exec(fmt.Sprintf(`CREATE INDEX IF NOT EXISTS "%s" ON "%s" (tax_jurisdiction_code, tax_group_used, tax_type, use_tax, posting_date)`,
		fmt.Sprintf("%s$Tax_Entry$jurisdiction", company), tableName)); err != nil {
		return fmt.Errorf("failed to create index jurisdiction: %w", err)
	}
	var keys []sift.Key
	for _, spec := range taxEntrySIFTSpecs() {
		keys = append(keys, sift.BuildKey(dbType, siftCompany, TaxEntryTableName, tableName, spec))
	}
	return sift.Sync(db, dbType, siftCompany, TaxEntryTableName, keys)
}

// taxEntrySIFTSpecs are the table's keys with sum_index_fields
func taxEntrySIFTSpecs() []sift.KeySpec {
	return []sift.KeySpec{}
}

// VerifySIFT compares the table's SIFT totals with its entries (Verify SIFT codeunit); with
// repair it rebuilds the keys whose totals differ.
func (t *TaxEntry) VerifySIFT(repair bool) ([]sift.VerifyResult, error) {
	tableName, siftCompany := fmt.Sprintf("%s$%s", t.company, TaxEntryTableName), t.company
	var results []sift.VerifyResult
	for _, spec := range taxEntrySIFTSpecs() {
		n, err := sift.VerifyKey(t.db, t.dbType, siftCompany, TaxEntryTableName, tableName, spec)
		if err != nil {
			return results, fmt.Errorf("%s: %w", spec.Name, err)
		}
		result := sift.VerifyResult{Table: TaxEntryTableName, Key: spec.Name, Differences: n}
		if n > 0 && repair {
			if err := sift.RebuildKey(t.db, t.dbType, siftCompany, TaxEntryTableName, tableName, spec); err != nil {
				return results, fmt.Errorf("%s: %w", spec.Name, err)
			}
			result.Rebuilt = true
		}
		results = append(results, result)
	}
	return results, nil
}

