	// Convert placeholders for PostgreSQL
	query = t.convertPlaceholders(query, len(args))
	query += t.forUpdate()

	rows, err := t.exec().Query(query, args...)
	if err != nil {
		fmt.Printf("Error: Failed to execute FindSet for Tax_Entry: %v\n", err)
		return false
	}

	t.currentRows = rows

	// Load first record
	return t.Next()
